WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_ip_leader'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '与领导相处', 'kp-ms-ip-leader', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "人际交往：与领导相处"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "尊重领导权威，服从安排，适时提出合理化建议。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、致命雷区"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "当面顶撞或越级上报：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果领导的决定有明显失误，千万不要当着同事的面顶撞！也不要直接越级找大领导告状。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、高分破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“委婉建议法”：如果是小瑕疵，私下里带着自己修改好的备选方案去领导办公室，委婉地说：“领导，关于那个项目，我又琢磨了一下，发现如果这么改可能效果更好，您帮忙把把关？”。如果领导坚持原意见（且不违法违规），【必须无条件执行】并在执行中努力弥补瑕疵。"}]}]}$$ AS jsonb), NULL, '与领导相处的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "人际交往", "领导关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ip_leader", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
